      o.type === 'task' ? o.stage : '', o.seriesId ? 'repeats' : ''].filter(Boolean).join(' · ')));
    mid.append(el('span', 'dn', o.title));
    row.append(bar, mid);
    if (o.type === 'task') row.append(tickButton(o));
    return row;
  }));
}

