import io, sys
p = '/home/max/ws/mine/calendar/popup.js'
s = io.open(p, encoding='utf-8').read()
E = []

# Switching scope rebuilds the draft, so it has to rebuild the baseline with it - otherwise
# `clean` is undefined and the popup reads as dirty for the rest of its life.
